/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-alpha-500:oklch(0 0 0 / 0.14);--chatcn-alpha-600:oklch(0 0 0 / 0.2);--chatcn-bg:oklch(1 0 0);--chatcn-border:var(--chatcn-gray-400);--chatcn-border-strong:var(--chatcn-gray-600);--chatcn-card:oklch(1 0 0);--chatcn-chart-1:oklch(0.560 0.170 255);--chatcn-chart-2:oklch(0.700 0.150 70);--chatcn-chart-3:oklch(0.600 0.120 170);--chatcn-chart-4:oklch(0.580 0.200 340);--chatcn-chart-5:oklch(0.640 0.170 40);--chatcn-chart-6:oklch(0.540 0.160 295);--chatcn-ease-out:cubic-bezier(0.23, 1, 0.32, 1);--chatcn-ease-standard:ease;--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-100:oklch(0.970 0 0);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-200:oklch(0.950 0 0);--chatcn-gray-300:oklch(0.930 0 0);--chatcn-gray-400:oklch(0.910 0 0);--chatcn-gray-600:oklch(0.800 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-gray-900:oklch(0.440 0 0);--chatcn-inset:oklch(0.975 0 0);--chatcn-press-scale:0.97;--chatcn-press-scale-icon:0.94;--chatcn-primary:var(--chatcn-gray-1000);--chatcn-primary-fg:var(--chatcn-bg);--chatcn-primary-hover:var(--chatcn-gray-900);--chatcn-radius-lg:12px;--chatcn-radius-md:8px;--chatcn-radius-sm:6px;--chatcn-radius-xs:4px;--chatcn-scrollbar:var(--chatcn-alpha-500);--chatcn-scrollbar-hover:var(--chatcn-alpha-600);--chatcn-shadow-border:0 0 0 1px oklch(0 0 0 / 0.08);--chatcn-shadow-md:0 0 0 1px oklch(0 0 0 / 0.06), 0 2px 4px -1px oklch(0 0 0 / 0.06), 0 8px 16px -4px oklch(0 0 0 / 0.08);--chatcn-shadow-sm:0 0 0 1px oklch(0 0 0 / 0.06), 0 1px 2px -1px oklch(0 0 0 / 0.06), 0 2px 4px oklch(0 0 0 / 0.04);--chatcn-shadow-xs:0 0 0 1px oklch(0 0 0 / 0.08), 0 1px 2px oklch(0 0 0 / 0.04);--chatcn-surface:oklch(1 0 0)}.dark{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-alpha-500:oklch(1 0 0 / 0.16);--chatcn-alpha-600:oklch(1 0 0 / 0.24);--chatcn-bg:oklch(0.145 0 0);--chatcn-border:var(--chatcn-gray-400);--chatcn-border-strong:var(--chatcn-gray-600);--chatcn-card:oklch(0.175 0 0);--chatcn-chart-1:oklch(0.700 0.150 252);--chatcn-chart-2:oklch(0.800 0.140 74);--chatcn-chart-3:oklch(0.740 0.120 170);--chatcn-chart-4:oklch(0.720 0.170 345);--chatcn-chart-5:oklch(0.740 0.150 45);--chatcn-chart-6:oklch(0.720 0.140 300);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-100:oklch(0.195 0 0);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-200:oklch(0.225 0 0);--chatcn-gray-300:oklch(0.255 0 0);--chatcn-gray-400:oklch(0.285 0 0);--chatcn-gray-600:oklch(0.410 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-gray-900:oklch(0.720 0 0);--chatcn-inset:oklch(0.155 0 0);--chatcn-primary:var(--chatcn-gray-1000);--chatcn-primary-fg:var(--chatcn-bg);--chatcn-primary-hover:var(--chatcn-gray-900);--chatcn-scrollbar:var(--chatcn-alpha-500);--chatcn-scrollbar-hover:var(--chatcn-alpha-600);--chatcn-shadow-border:0 0 0 1px oklch(1 0 0 / 0.08);--chatcn-shadow-md:0 0 0 1px oklch(1 0 0 / 0.09), inset 0 1px 0 oklch(1 0 0 / 0.04), 0 8px 16px -4px oklch(0 0 0 / 0.5);--chatcn-shadow-sm:0 0 0 1px oklch(1 0 0 / 0.08), inset 0 1px 0 oklch(1 0 0 / 0.03), 0 2px 4px oklch(0 0 0 / 0.4);--chatcn-shadow-xs:0 0 0 1px oklch(1 0 0 / 0.08), 0 1px 2px oklch(0 0 0 / 0.4);--chatcn-surface:oklch(0.205 0 0)}.chatcn-focus{}.chatcn-focus:focus-visible{outline: 2px solid var(--chatcn-accent); outline-offset: 2px;}.chatcn-scroll{scrollbar-width: thin; scrollbar-color: var(--chatcn-scrollbar) transparent;}.chatcn-scroll:hover{scrollbar-color: var(--chatcn-scrollbar-hover) transparent;}.chatcn-scroll::-webkit-scrollbar{width: 10px; height: 10px;}.chatcn-scroll::-webkit-scrollbar-track, .chatcn-scroll::-webkit-scrollbar-corner{background: transparent;}.chatcn-scroll::-webkit-scrollbar-thumb{background-color: var(--chatcn-scrollbar); background-clip: content-box; border: 3px solid transparent; border-radius: 9999px;}.chatcn-scroll::-webkit-scrollbar-thumb:hover{background-color: var(--chatcn-scrollbar-hover);}@media (prefers-reduced-motion: reduce){:root{--chatcn-press-scale:1;--chatcn-press-scale-icon:1;--chatcn-enter-scale:1}}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-chart")) {
  const style = document.createElement("style")
  style.id = "chatcn-chart"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * Proportion bar: the pie alternative. One 100% bar, 2 px gaps, labelled rows underneath.
 * -----------------------------------------------------------------------------------------------*/

export interface ProportionItem {
  label: string
  value: number
}

export interface ProportionBarProps extends React.ComponentProps<"div"> {
  items: ProportionItem[]
  format?: (value: number) => string
  /** Bar thickness in px. */
  size?: number
  /** Hide the labelled rows under the bar. */
  hideLabels?: boolean
  streaming?: boolean
  highlight?: string
}

/* -------------------------------------------------------------------------------------------------
 * Encodings
 *
 * Series take the categorical chart palette (`--chatcn-chart-1` to `-6`): hues picked to stay
 * distinct for the common color blindness types. Lines also keep distinct dash patterns and end
 * markers, and every chart has a legend and a data table, so no series depends on hue alone.
 * -----------------------------------------------------------------------------------------------*/

type Fill =
  | { kind: "solid"; color: string }
  | { kind: "hatch" | "dots"; color: string; ground: string; angle: number }

const FILLS: Fill[] = [
  { kind: "solid", color: "var(--chatcn-chart-1)" },
  { kind: "solid", color: "var(--chatcn-chart-2)" },
  { kind: "solid", color: "var(--chatcn-chart-3)" },
  { kind: "solid", color: "var(--chatcn-chart-4)" },
  { kind: "solid", color: "var(--chatcn-chart-5)" },
  { kind: "solid", color: "var(--chatcn-chart-6)" },
]

/* -------------------------------------------------------------------------------------------------
 * Swatches and patterns
 * -----------------------------------------------------------------------------------------------*/

function PatternDefs({ id }: { id: string }) {
  return (
    <defs>
      {FILLS.map((fill, i) =>
        fill.kind === "solid" ? null : (
          <pattern
            key={i}
            id={`${id}-p${i}`}
            patternUnits="userSpaceOnUse"
            width={fill.kind === "dots" ? 4 : 5}
            height={fill.kind === "dots" ? 4 : 5}
            patternTransform={fill.kind === "hatch" ? `rotate(${fill.angle})` : undefined}
          >
            <rect width="5" height="5" fill={fill.ground} />
            {fill.kind === "hatch" ? (
              <line x1="0" y1="0" x2="0" y2="5" stroke={fill.color} strokeWidth="2" />
            ) : (
              <circle cx="2" cy="2" r="0.9" fill={fill.color} />
            )}
          </pattern>
        ),
      )}
    </defs>
  )
}

function fillFor(id: string, index: number) {
  const fill = FILLS[index % FILLS.length] as Fill
  return fill.kind === "solid" ? fill.color : `url(#${id}-p${index % FILLS.length})`
}

type Marker = "circle" | "square" | "diamond" | "triangle"

const STROKES: { color: string; dash?: string; marker: Marker }[] = [
  { color: "var(--chatcn-chart-1)", marker: "circle" },
  { color: "var(--chatcn-chart-2)", marker: "square" },
  { color: "var(--chatcn-chart-3)", dash: "6 4", marker: "diamond" },
  { color: "var(--chatcn-chart-4)", dash: "2 4", marker: "triangle" },
  { color: "var(--chatcn-chart-5)", marker: "circle" },
  { color: "var(--chatcn-chart-6)", dash: "6 4", marker: "square" },
]

/** Legend and tooltip key. Mirrors the mark: a filled square for bars, a short stroke for lines. */
function SeriesKey({ index, kind }: { index: number; kind: "fill" | "line" }) {
  const id = React.useId()
  if (kind === "line") {
    const stroke = STROKES[index % STROKES.length] as (typeof STROKES)[number]
    return (
      <svg aria-hidden="true" width="14" height="8" className="shrink-0 overflow-visible">
        <line
          x1="1"
          y1="4"
          x2="13"
          y2="4"
          stroke={stroke.color}
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={stroke.dash ? stroke.dash.replace("6 4", "4 3") : undefined}
        />
      </svg>
    )
  }
  return (
    <svg aria-hidden="true" width="10" height="10" className="shrink-0">
      <PatternDefs id={id} />
      <rect width="10" height="10" rx="2.5" fill={fillFor(id, index)} />
    </svg>
  )
}

export function ProportionBar({
  items,
  format = (v) => String(v),
  size = 12,
  hideLabels,
  streaming,
  highlight,
  className,
  ...props
}: ProportionBarProps) {
  const id = React.useId()
  const positive = items.filter((it) => it.value > 0)
  const total = positive.reduce((n, it) => n + it.value, 0)
  const percent = new Intl.NumberFormat("en-US", { style: "percent", maximumFractionDigits: 0 })
  return (
    <div data-slot="proportion-bar" className={cn("flex flex-col gap-3", className)} {...props}>
      <div className="flex w-full gap-0.5 overflow-hidden" style={{ height: size }}>
        {total === 0 ? (
          <div className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-full flex-1" />
        ) : (
          positive.map((it, _i) => (
            <svg
              key={it.label}
              aria-hidden="true"
              data-slot="chart-mark"
              data-enter={streaming ? "fade" : undefined}
              className={cn(
                "h-full min-w-0.5 shrink-0 first:rounded-s-[4px] last:rounded-e-[4px]",
                "ease-(--chatcn-ease-out) transition-[opacity] duration-150",
                highlight !== undefined && highlight !== it.label && "opacity-40",
              )}
              style={{ flexBasis: `calc(${(it.value / total) * 100}% - 2px)`, flexGrow: 1 }}
            >
              <PatternDefs id={id} />
              <rect width="100%" height="100%" fill={fillFor(id, items.indexOf(it))} />
            </svg>
          ))
        )}
      </div>
      {hideLabels ? null : (
        <ul className="grid grid-cols-[repeat(auto-fill,minmax(10rem,1fr))] gap-x-4 gap-y-1.5">
          {items.map((it, i) => (
            <li key={it.label} className="text-[0.8125rem]/[1.25rem] flex min-w-0 items-center gap-2">
              <SeriesKey index={i} kind="fill" />
              <span className="text-(color:--chatcn-fg-muted) min-w-0 truncate">{it.label}</span>
              <span className="text-(color:--chatcn-fg) ms-auto shrink-0 font-medium tabular-nums">
                {total > 0 ? percent.format(Math.max(0, it.value) / total) : "-"}
              </span>
              <span className="text-(color:--chatcn-fg-subtle) text-[0.75rem]/[1rem] shrink-0 tabular-nums">
                {format(it.value)}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type ChartType = "bar" | "line" | "area" | "proportion"

export type ChartDatum = Record<string, string | number | null | undefined>

export interface ChartSeries {
  /** Field in each datum that holds this series' value. */
  key: string
  /** Name shown in the legend, tooltip and table. Defaults to a readable `key`. */
  label?: string
}

export type ChartValueFormat = "number" | "compact" | "percent" | "currency"

export interface ChartProps extends Omit<React.ComponentProps<"figure">, "title"> {
  type?: ChartType
  /** One object per category or point. Partial arrays render as they stream. */
  data?: ChartDatum[]
  /** Field that holds the category or x value. Defaults to `label`. */
  xKey?: string
  /** Value fields. Defaults to `["value"]`. At most six series are encoded. */
  series?: Array<string | ChartSeries>
  title?: React.ReactNode
  description?: React.ReactNode
  /** `horizontal` bars suit long category names and rankings. */
  layout?: "vertical" | "horizontal"
  /** Stack bar series instead of grouping them. */
  stacked?: boolean
  /** Plot height in px. The frame holds it from the first paint, so nothing shifts. */
  height?: number
  valueFormat?: ChartValueFormat
  /** Unit after each value, joined with a non-breaking space: `ms`, `MB`. */
  unit?: string
  /** ISO currency for `valueFormat="currency"`. Defaults to USD. */
  currency?: string
  /** Custom value formatter. Wins over `valueFormat` and `unit`. */
  format?: (value: number) => string
  locale?: string
  /** Fixed value domain. Pass one while streaming so the axis never rescales under the reader. */
  domain?: [number, number]
  /** Slots to reserve while points stream in, so earlier points never move. */
  expectedCount?: number
  /** Direct value labels. `auto` labels when every label fits. */
  valueLabels?: "auto" | "all" | "none"
  /** Category to emphasize. The rest step back. */
  highlight?: string
  /** One sentence for screen readers. Generated from the data when omitted. */
  summary?: string
  /** Nothing to draw yet: a static skeleton at the final size. */
  loading?: boolean
  /** More points may arrive. New marks reveal once, old ones stay put. */
  streaming?: boolean
  /** Rendering failed. The table stays available when there is data. */
  error?: React.ReactNode
  /** Shown when the data is empty and nothing is streaming. */
  empty?: React.ReactNode
  /** Source line under the plot. */
  footer?: React.ReactNode
  variant?: "card" | "plain"
  view?: "chart" | "table"
  defaultView?: "chart" | "table"
  onViewChange?: (view: "chart" | "table") => void
}

const MAX_SERIES = 6

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

function humanize(key: string) {
  const words = key
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .trim()
  return words.charAt(0).toUpperCase() + words.slice(1).toLowerCase()
}

function normalizeSeries(series: ChartProps["series"]): Required<ChartSeries>[] {
  const list = series && series.length > 0 ? series : ["value"]
  return list
    .slice(0, MAX_SERIES)
    .map((s) =>
      typeof s === "string"
        ? { key: s, label: humanize(s) }
        : { key: s.key, label: s.label ?? humanize(s.key) },
    )
}

const NBSP = " "

function makeFormatter({
  format,
  valueFormat = "number",
  unit,
  currency = "USD",
  locale = "en-US",
}: Pick<ChartProps, "format" | "valueFormat" | "unit" | "currency" | "locale">) {
  if (format) return { full: format, tick: format }
  const options: Intl.NumberFormatOptions =
    valueFormat === "currency"
      ? { style: "currency", currency, minimumFractionDigits: 0, maximumFractionDigits: 2 }
      : valueFormat === "percent"
        ? { style: "percent", maximumFractionDigits: 1 }
        : { maximumFractionDigits: 2 }
  const full = new Intl.NumberFormat(locale, options)
  const compact = new Intl.NumberFormat(locale, {
    ...options,
    notation: "compact",
    maximumFractionDigits: 1,
  })
  const suffix = unit ? `${NBSP}${unit}` : ""
  const useCompact = valueFormat === "compact"
  return {
    full: (v: number) => `${(useCompact ? compact : full).format(v)}${suffix}`,
    // Ticks compact from 1,000 up so the gutter stays narrow.
    tick: (v: number) => `${(Math.abs(v) >= 1000 ? compact : full).format(v)}${suffix}`,
  }
}

function useWidth<T extends HTMLElement>() {
  const [node, setNode] = React.useState<T | null>(null)
  const [width, setWidth] = React.useState(0)
  React.useLayoutEffect(() => {
    if (!node) return
    setWidth(node.getBoundingClientRect().width)
    const observer = new ResizeObserver(([entry]) => {
      if (entry) setWidth(entry.contentRect.width)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [node])
  return [setNode, width] as const
}

function toNumber(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value
  if (typeof value === "string" && value.trim() !== "") {
    const n = Number(value)
    return Number.isFinite(n) ? n : null
  }
  return null
}

/* -------------------------------------------------------------------------------------------------
 * Chart
 * -----------------------------------------------------------------------------------------------*/

function describe(
  type: ChartType,
  data: ChartDatum[],
  xKey: string,
  series: Required<ChartSeries>[],
  format: (v: number) => string,
) {
  if (data.length === 0) return "Chart with no data yet."
  const kind =
    type === "bar"
      ? "Bar chart"
      : type === "line"
        ? "Line chart"
        : type === "area"
          ? "Area chart"
          : "Proportion bar"
  const first = String(data[0]?.[xKey] ?? "")
  const last = String(data.at(-1)?.[xKey] ?? "")
  const parts = series.map((s) => {
    let max: { v: number; at: string } | null = null
    for (const d of data) {
      const v = toNumber(d[s.key])
      if (v !== null && (!max || v > max.v)) max = { v, at: String(d[xKey] ?? "") }
    }
    return max ? `${s.label} peaks at ${format(max.v)} (${max.at})` : `${s.label} has no values`
  })
  return `${kind}, ${data.length} ${data.length === 1 ? "point" : "points"} from ${first} to ${last}. ${parts.join(". ")}. Use arrow keys to read values.`
}

/* -------------------------------------------------------------------------------------------------
 * Motion: each mark reveals from its baseline with clip-path when it is inserted. CSS animations
 * run on insert only, so re-renders never replay them and streamed points reveal on their own.
 * -----------------------------------------------------------------------------------------------*/

const chartCss = `
@keyframes chatcn-chart-rise { from { clip-path: inset(100% 0 0 0) } to { clip-path: inset(0 0 0 0) } }
@keyframes chatcn-chart-grow { from { clip-path: inset(0 100% 0 0) } to { clip-path: inset(0 0 0 0) } }
@keyframes chatcn-chart-fade { from { opacity: 0 } to { opacity: 1 } }
[data-slot=chart-mark][data-enter=rise] { animation: chatcn-chart-rise 280ms var(--chatcn-ease-out) both }
[data-slot=chart-mark][data-enter=grow] { animation: chatcn-chart-grow 280ms var(--chatcn-ease-out) both }
[data-slot=chart-mark][data-enter=draw] { animation: chatcn-chart-grow 300ms var(--chatcn-ease-out) both }
[data-slot=chart-mark][data-enter=fade] { animation: chatcn-chart-fade 200ms var(--chatcn-ease-out) both }
@media (prefers-reduced-motion: reduce) {
  [data-slot=chart-mark][data-enter] { animation: chatcn-chart-fade 150ms linear both }
}
`

interface TooltipProps {
  content: React.ReactNode
  children: React.ReactElement
  side?: "top" | "bottom" | "left" | "right"
  align?: "start" | "center" | "end"
  /** A shortcut hint shown after the label, for example `⌘C`. */
  shortcut?: React.ReactNode
}

function Tooltip({ content, children, side = "top", align = "center", shortcut }: TooltipProps) {
  return (
    <TooltipPrimitive.Root>
      <TooltipPrimitive.Trigger render={children} />
      <TooltipPrimitive.Portal>
        <TooltipPrimitive.Positioner side={side} align={align} sideOffset={6} className="z-50">
          <TooltipPrimitive.Popup
            data-slot="tooltip"
            className={cn(
              "rounded-(--chatcn-radius-sm) bg-(color:--chatcn-fg) text-[0.75rem]/[1rem] text-(color:--chatcn-bg) shadow-(--chatcn-shadow-md) flex max-w-xs origin-(--transform-origin) items-center gap-2 px-2 py-1 font-medium text-pretty",
              "ease-(--chatcn-ease-out) transition-[opacity,scale] duration-125",
              "data-[ending-style]:scale-97 data-[ending-style]:opacity-0 data-[ending-style]:duration-100 data-[starting-style]:scale-97 data-[starting-style]:opacity-0",
              // Once one tooltip is open, the next appears without animation. Reduced motion keeps
              // only the fade.
              "data-[instant]:transition-none motion-reduce:transition-opacity motion-reduce:data-[ending-style]:scale-100 motion-reduce:data-[starting-style]:scale-100",
            )}
          >
            {content}
            {shortcut ? <span className="font-normal opacity-60">{shortcut}</span> : null}
          </TooltipPrimitive.Popup>
        </TooltipPrimitive.Positioner>
      </TooltipPrimitive.Portal>
    </TooltipPrimitive.Root>
  )
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

interface ButtonProps extends React.ComponentProps<"button"> {
  variant?: ButtonVariant
  size?: ButtonSize
}

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
