/* -------------------------------------------------------------------------------------------------
 * Plot
 * -----------------------------------------------------------------------------------------------*/

interface PlotProps {
  type: Exclude<ChartType, "proportion">
  data: ChartDatum[]
  xKey: string
  series: Required<ChartSeries>[]
  layout: "vertical" | "horizontal"
  stacked: boolean
  height: number
  width: number
  fmt: { full: (v: number) => string; tick: (v: number) => string }
  domain?: [number, number]
  expectedCount?: number
  valueLabels: "auto" | "all" | "none"
  highlight?: string
  streaming: boolean
  summary: string
  tableId: string
  /** Reports whether line end labels fit, so the legend can step aside. */
  onEndLabels?: (fit: boolean) => void
}

/** Round numbers for an axis: steps of 1, 2, 2.5 or 5 times a power of ten. */
function niceTicks(min: number, max: number, count = 4) {
  if (min === max) max = min + 1
  const span = max - min
  const raw = span / count
  const power = 10 ** Math.floor(Math.log10(raw))
  const step = ([1, 2, 2.5, 5, 10].find((m) => m * power >= raw) ?? 10) * power
  const lo = Math.floor(min / step) * step
  const hi = Math.ceil(max / step) * step
  const ticks: number[] = []
  for (let v = lo; v <= hi + step / 2; v += step) ticks.push(Number(v.toFixed(10)))
  return { ticks, lo, hi }
}

function findLast<T>(list: T[], fn: (item: T) => boolean) {
  for (let i = list.length - 1; i >= 0; i--) if (fn(list[i] as T)) return i
  return -1
}

const PAD_TOP = 8

const X_AXIS = 24

const AXIS_FONT = "12px Geist, ui-sans-serif, system-ui, sans-serif"

let measureCtx: CanvasRenderingContext2D | null | undefined

/** Text width for label fitting. Falls back to an average glyph width outside the browser. */
function textWidth(text: string, font = AXIS_FONT) {
  if (measureCtx === undefined) {
    measureCtx =
      typeof document === "undefined" ? null : document.createElement("canvas").getContext("2d")
  }
  if (!measureCtx) return text.length * 6.6
  measureCtx.font = font
  return measureCtx.measureText(text).width
}

/**
 * The interactive layer: one focus stop for the whole plot. Arrow keys walk the categories, the
 * pointer snaps to the nearest one, and a polite live region reads the active values.
 */
function PlotFrame({
  width,
  height,
  summary,
  tableId,
  count,
  labels,
  active,
  setActive,
  setViaKeyboard,
  onFocusChange,
  axis,
  bandOf,
  tooltip,
  children,
}: {
  width: number
  height: number
  summary: string
  tableId: string
  count: number
  labels: string[]
  active: number | null
  setActive: (i: number | null) => void
  setViaKeyboard: (v: boolean) => void
  onFocusChange: () => void
  axis: "x" | "y"
  bandOf: (pos: number) => number
  tooltip: React.ReactNode
  children: React.ReactNode
}) {
  const filled = labels.length
  const clamp = (i: number) => Math.max(0, Math.min(filled - 1, i))
  return (
    // biome-ignore lint/a11y/useSemanticElements: a focusable chart region, not a set of form controls
    <div
      data-slot="chart-plot"
      tabIndex={filled > 0 ? 0 : undefined}
      role="group"
      aria-roledescription="chart"
      aria-label={summary}
      aria-describedby={tableId}
      className="chatcn-focus rounded-(--chatcn-radius-sm) relative outline-none select-none"
      style={{ height }}
      onPointerMove={(event) => {
        if (filled === 0) return
        const rect = event.currentTarget.getBoundingClientRect()
        const pos = axis === "x" ? event.clientX - rect.left : event.clientY - rect.top
        setViaKeyboard(false)
        setActive(clamp(bandOf(pos)))
      }}
      onPointerLeave={() => {
        setActive(null)
        onFocusChange()
      }}
      onBlur={() => setActive(null)}
      onKeyDown={(event) => {
        if (filled === 0) return
        const keys: Record<string, number> = {
          ArrowRight: 1,
          ArrowDown: 1,
          ArrowLeft: -1,
          ArrowUp: -1,
        }
        if (event.key in keys) {
          event.preventDefault()
          setViaKeyboard(true)
          setActive(clamp(active === null ? 0 : active + (keys[event.key] as number)))
        } else if (event.key === "Home" || event.key === "End") {
          event.preventDefault()
          setViaKeyboard(true)
          setActive(event.key === "Home" ? 0 : filled - 1)
        } else if (event.key === "Escape") {
          setActive(null)
        }
      }}
    >
      {width > 0 ? (
        <svg
          aria-hidden="true"
          width={width}
          height={height}
          className="block overflow-visible"
          data-count={count}
        >
          {children}
        </svg>
      ) : null}
      {tooltip}
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Tooltip
 * -----------------------------------------------------------------------------------------------*/

interface TooltipRow {
  index: number
  label: string
  value: string
}

function ChartTooltip({
  title,
  rows,
  kind,
  left,
  top,
  containerWidth,
  instant,
}: {
  title: string
  rows: TooltipRow[]
  kind: "fill" | "line"
  left: number
  top: number
  containerWidth: number
  instant: boolean
}) {
  const ref = React.useRef<HTMLDivElement>(null)
  const [w, setW] = React.useState(140)
  React.useLayoutEffect(() => {
    if (ref.current) setW(ref.current.offsetWidth)
  })
  // Sit to the right of the pointer, flip left near the edge.
  const x = left + 12 + w > containerWidth ? Math.max(0, left - 12 - w) : left + 12
  return (
    <div
      ref={ref}
      data-slot="chart-tooltip"
      aria-hidden="true"
      style={{ transform: `translate(${x}px, ${top}px)` }}
      className={cn(
        "rounded-(--chatcn-radius-md) bg-(color:--chatcn-surface) shadow-(--chatcn-shadow-md) pointer-events-none absolute start-0 top-0 z-10 min-w-28 px-2.5 py-2",
        "dark:shadow-(--chatcn-shadow-border)",
        !instant && "motion-safe:animate-[chatcn-tooltip-in_125ms_var(--chatcn-ease-out)]",
      )}
    >
      <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) mb-1 whitespace-nowrap">{title}</p>
      <ul className="flex flex-col gap-0.5">
        {rows.map((row) => (
          <li key={row.index} className="flex items-center gap-2 whitespace-nowrap">
            {rows.length > 1 ? <SeriesKey index={row.index} kind={kind} /> : null}
            <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) font-medium tabular-nums">
              {row.value}
            </span>
            {rows.length > 1 ? (
              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle)">{row.label}</span>
            ) : null}
          </li>
        ))}
      </ul>
    </div>
  )
}

function valueText(value: unknown, format: (v: number) => string) {
  const n = toNumber(value)
  return n === null ? "No value" : format(n)
}

function rowExtent(
  d: ChartDatum | undefined,
  series: Required<ChartSeries>[],
  stacked: boolean,
  scale: (v: number) => number,
  zero: number,
) {
  if (!d) return 0
  if (stacked) return scale(series.reduce((n, s) => n + Math.max(0, toNumber(d[s.key]) ?? 0), 0))
  return Math.max(zero, ...series.map((s) => scale(toNumber(d[s.key]) ?? 0)))
}

function truncate(text: string, max: number) {
  if (textWidth(text) <= max) return text
  let t = text
  while (t.length > 1 && textWidth(`${t}…`) > max) t = t.slice(0, -1)
  return `${t.trimEnd()}…`
}

/** A bar with a 4 px rounded data end and a square end at the baseline. */
function barPath(
  x: number,
  y: number,
  w: number,
  h: number,
  end: "top" | "bottom" | "right" | "left",
  rounded = true,
) {
  if (w <= 0 || h <= 0) return ""
  const r = rounded ? Math.min(4, w / 2, h / 2) : 0
  const x2 = x + w
  const y2 = y + h
  switch (end) {
    case "top":
      return `M${x},${y2}V${y + r}Q${x},${y} ${x + r},${y}H${x2 - r}Q${x2},${y} ${x2},${y + r}V${y2}Z`
    case "bottom":
      return `M${x},${y}V${y2 - r}Q${x},${y2} ${x + r},${y2}H${x2 - r}Q${x2},${y2} ${x2},${y2 - r}V${y}Z`
    case "right":
      return `M${x},${y}H${x2 - r}Q${x2},${y} ${x2},${y + r}V${y2 - r}Q${x2},${y2} ${x2 - r},${y2}H${x}Z`
    case "left":
      return `M${x2},${y}H${x + r}Q${x},${y} ${x},${y + r}V${y2 - r}Q${x},${y2} ${x + r},${y2}H${x2}Z`
  }
}

function MarkerShape({
  marker,
  x,
  y,
  color,
  r = 4,
}: {
  marker: Marker
  x: number
  y: number
  color: string
  r?: number
}) {
  // Every marker wears a 2 px ring in the surface color so it stays legible where lines cross.
  const ring = { stroke: "var(--chatcn-card)", strokeWidth: 2, paintOrder: "stroke" as const }
  switch (marker) {
    case "square":
      return (
        <rect
          x={x - r * 0.85}
          y={y - r * 0.85}
          width={r * 1.7}
          height={r * 1.7}
          rx={1}
          fill={color}
          {...ring}
        />
      )
    case "diamond":
      return (
        <path
          d={`M${x},${y - r * 1.15}L${x + r * 1.15},${y}L${x},${y + r * 1.15}L${x - r * 1.15},${y}Z`}
          fill={color}
          {...ring}
        />
      )
    case "triangle":
      return (
        <path
          d={`M${x},${y - r * 1.1}L${x + r * 1.1},${y + r * 0.8}L${x - r * 1.1},${y + r * 0.8}Z`}
          fill={color}
          {...ring}
        />
      )
    default:
      return <circle cx={x} cy={y} r={r} fill={color} {...ring} />
  }
}

function Plot(props: PlotProps) {
  const {
    type,
    data,
    xKey,
    series,
    layout,
    stacked,
    height,
    width,
    fmt,
    domain,
    expectedCount,
    valueLabels,
    highlight,
    streaming,
    summary,
    tableId,
    onEndLabels,
  } = props
  const id = React.useId()
  const [active, setActive] = React.useState<number | null>(null)
  const [viaKeyboard, setViaKeyboard] = React.useState(false)
  const [shownOnce, setShownOnce] = React.useState(false)
  const horizontal = type === "bar" && layout === "horizontal"
  const isLine = type === "line" || type === "area"
  const multi = series.length > 1

  // Value domain: zero-based for bars and areas, data-fitted for lines.
  const values: number[] = []
  for (const d of data) {
    if (stacked && type === "bar") {
      let pos = 0
      let neg = 0
      for (const s of series) {
        const v = toNumber(d[s.key]) ?? 0
        if (v >= 0) pos += v
        else neg += v
      }
      values.push(pos, neg)
    } else for (const s of series) values.push(toNumber(d[s.key]) ?? 0)
  }
  const dataMin = values.length ? Math.min(...values) : 0
  const dataMax = values.length ? Math.max(...values) : 1
  let lo = domain?.[0] ?? Math.min(0, dataMin)
  let hi = domain?.[1] ?? Math.max(0, dataMax)
  if (type === "line" && !domain && dataMin > 0) {
    // Lines need not start at zero; leave a little air under the lowest point.
    lo = Math.max(0, dataMin - (dataMax - dataMin) * 0.25)
  }
  const nice = niceTicks(lo, hi, horizontal ? 4 : height < 160 ? 3 : 4)
  if (!domain) {
    lo = nice.lo
    hi = nice.hi
  }
  const ticks = nice.ticks.filter((t) => t >= lo - 1e-9 && t <= hi + 1e-9)

  const count = Math.max(data.length, expectedCount ?? 0, 1)
  const labels = data.map((d) => String(d[xKey] ?? ""))

  // Lines get a right gutter for direct end labels when they fit.
  const endLabels = isLine
    ? series.map((s) => {
        const lastIdx = findLast(data, (d) => toNumber(d[s.key]) !== null)
        return { s, lastIdx, text: multi ? s.label : "" }
      })
    : []
  const plotH = height - PAD_TOP - X_AXIS
  const yOf = (v: number) => PAD_TOP + plotH - ((v - lo) / (hi - lo || 1)) * plotH
  // End label positions for lines; drop them if any two would collide. Vertical positions do not
  // depend on the width, so this decides the right gutter before the x scale exists.
  const ends = endLabels
    .filter((e) => e.lastIdx >= 0)
    .map((e) => ({ ...e, y: yOf(toNumber(data[e.lastIdx]?.[e.s.key]) ?? 0) }))
  const sorted = [...ends].sort((a, b) => a.y - b.y)
  const collide = sorted.some((e, i) => i > 0 && e.y - (sorted[i - 1] as { y: number }).y < 14)
  const showEnds = isLine && multi && !collide && !streaming
  React.useEffect(() => onEndLabels?.(showEnds), [showEnds, onEndLabels])

  /* ---------- Horizontal bars: labels on the left, values at the tips, no y axis ---------- */
  if (horizontal) {
    const labelW = Math.min(
      Math.max(...labels.map((l) => textWidth(l)), 40) + 18,
      Math.round(width * 0.38),
    )
    const tipW =
      Math.max(
        ...data.map((d) => textWidth(fmt.full(toNumber(d[series[0]?.key ?? ""] ?? 0) ?? 0))),
        24,
      ) + 10
    const plotW = Math.max(40, width - labelW - (stacked || multi ? 8 : tipW))
    const band = height / count
    const thick = Math.min(
      multi && !stacked ? 14 : 20,
      (band * 0.72) / (multi && !stacked ? series.length : 1),
    )
    const scale = (v: number) => ((v - lo) / (hi - lo || 1)) * plotW
    const zero = scale(Math.max(lo, 0))
    return (
      <PlotFrame
        {...{ width, height, summary, tableId, count, active, setActive, setViaKeyboard, labels }}
        onFocusChange={() => setShownOnce(true)}
        axis="y"
        bandOf={(y) => Math.floor(y / band)}
        tooltip={
          active !== null && data[active] ? (
            <ChartTooltip
              title={labels[active] ?? ""}
              rows={series.map((s, i) => ({
                index: i,
                label: s.label,
                value: valueText(data[active]?.[s.key], fmt.full),
              }))}
              kind="fill"
              left={labelW + Math.min(plotW, rowExtent(data[active], series, stacked, scale, zero))}
              top={Math.max(0, active * band + band / 2 - 20)}
              containerWidth={width}
              instant={viaKeyboard || shownOnce}
            />
          ) : null
        }
      >
        <PatternDefs id={id} />
        {data.map((d, row) => {
          const y0 = row * band + (band - thick * (multi && !stacked ? series.length : 1)) / 2
          const dim = highlight !== undefined && highlight !== labels[row]
          const isActive = active === row
          let acc = zero
          return (
            <g
              key={labels[row] || row}
              opacity={active !== null && !isActive ? 0.55 : dim ? 0.4 : 1}
              className="transition-opacity duration-150"
            >
              <text
                x={labelW - 12}
                y={row * band + band / 2}
                dy="0.35em"
                textAnchor="end"
                className="fill-(color:--chatcn-fg-muted) text-[0.75rem]/[1rem]"
              >
                {truncate(labels[row] ?? "", labelW - 14)}
              </text>
              {series.map((s, si) => {
                const v = toNumber(d[s.key])
                if (v === null) return null
                if (stacked) {
                  const w = Math.max(
                    0,
                    scale(v + lo) - scale(lo) - (si < series.length - 1 ? 2 : 0),
                  )
                  const x = labelW + acc
                  acc += scale(v + lo) - scale(lo)
                  const last =
                    si === series.length - 1 ||
                    series.slice(si + 1).every((n) => !toNumber(d[n.key]))
                  return (
                    <path
                      key={s.key}
                      data-slot="chart-mark"
                      data-enter="grow"
                      d={barPath(x, y0, w, thick, "right", last)}
                      fill={fillFor(id, si)}
                    />
                  )
                }
                const y = y0 + (multi ? si * thick : 0)
                const w = Math.abs(scale(v) - zero)
                const x = labelW + Math.min(zero, scale(v))
                return (
                  <path
                    key={s.key}
                    data-slot="chart-mark"
                    data-enter="grow"
                    d={barPath(
                      x,
                      y + (multi ? 1 : 0),
                      w,
                      thick - (multi ? 2 : 0),
                      v < 0 ? "left" : "right",
                    )}
                    fill={fillFor(id, si)}
                  />
                )
              })}
              {!stacked && !multi && valueLabels !== "none" ? (
                <text
                  x={labelW + scale(toNumber(d[series[0]?.key ?? ""]) ?? 0) + 6}
                  y={row * band + band / 2}
                  dy="0.35em"
                  className="fill-(color:--chatcn-fg) text-[0.75rem]/[1rem] tabular-nums"
                >
                  {valueText(d[series[0]?.key ?? ""], fmt.full)}
                </text>
              ) : null}
            </g>
          )
        })}
      </PlotFrame>
    )
  }

  /* ---------- Columns, lines and areas: y axis on the left, categories below ---------- */
  const gutter = Math.ceil(Math.max(...ticks.map((t) => textWidth(fmt.tick(t))), 12)) + 10
  const endW = showEnds
    ? Math.min(120, Math.max(...ends.map((e) => textWidth(e.text))) + 14)
    : isLine
      ? 8
      : 0

  const plotW = Math.max(40, width - gutter - endW)
  const band = plotW / count
  const xOf = (i: number) =>
    isLine
      ? gutter + (count === 1 ? plotW / 2 : (i / (count - 1)) * plotW)
      : gutter + band * i + band / 2

  // Thin the x labels so they never collide.
  const labelEvery = (() => {
    const widest = Math.max(...labels.map((l) => textWidth(l)), 1) + 12
    const spacing = isLine ? plotW / Math.max(1, count - 1) : band
    return Math.max(1, Math.ceil(widest / Math.max(1, spacing)))
  })()

  const crosshair = active !== null && isLine ? xOf(active) : null
  const zeroY = yOf(Math.max(lo, Math.min(0, hi)))

  // Column value labels: every bar when each label clears its neighbours with room to breathe;
  // when they would crowd (a phone), only the highlighted bar keeps its label.
  const colKey = series[0]?.key ?? ""
  const colRoom =
    type === "bar" && !multi && valueLabels !== "none"
      ? valueLabels === "all" ||
        data.every((d) => textWidth(valueText(d[colKey], fmt.full)) + 12 < band)
      : false
  const colLabelFor = (label: string) =>
    colRoom ||
    (type === "bar" &&
      !multi &&
      valueLabels === "auto" &&
      highlight !== undefined &&
      highlight === label &&
      data.every((d) => textWidth(valueText(d[colKey], fmt.full)) + 4 < band * 3))

  const barW =
    multi && !stacked ? Math.min(16, (band * 0.72) / series.length) : Math.min(24, band * 0.6)

  return (
    <PlotFrame
      {...{ width, height, summary, tableId, count, active, setActive, setViaKeyboard, labels }}
      onFocusChange={() => setShownOnce(true)}
      axis="x"
      bandOf={(x) => {
        if (isLine) return Math.round(((x - gutter) / plotW) * (count - 1))
        return Math.floor((x - gutter) / band)
      }}
      tooltip={
        active !== null && data[active] ? (
          <ChartTooltip
            title={labels[active] ?? ""}
            rows={series.map((s, i) => ({
              index: i,
              label: s.label,
              value: valueText(data[active]?.[s.key], fmt.full),
            }))}
            kind={isLine ? "line" : "fill"}
            left={xOf(active)}
            top={PAD_TOP}
            containerWidth={width}
            instant={viaKeyboard || shownOnce}
          />
        ) : null
      }
    >
      <PatternDefs id={id} />
      {/* Grid: hairlines one step off the surface; the zero line is stronger. */}
      <g data-slot="chart-grid">
        {ticks.map((t) => (
          <g key={t}>
            <line
              x1={gutter}
              x2={gutter + plotW}
              y1={Math.round(yOf(t)) + 0.5}
              y2={Math.round(yOf(t)) + 0.5}
              stroke={t === 0 ? "var(--chatcn-border-strong)" : "var(--chatcn-gray-300)"}
              strokeWidth="1"
            />
            <text
              x={gutter - 8}
              y={yOf(t)}
              dy="0.35em"
              textAnchor="end"
              className="fill-(color:--chatcn-fg-subtle) text-[0.75rem]/[1rem] tabular-nums"
            >
              {fmt.tick(t)}
            </text>
          </g>
        ))}
        {labels.map((l, i) =>
          i % labelEvery === 0 || (isLine && i === labels.length - 1 && labelEvery === 1) ? (
            <text
              key={i}
              x={xOf(i)}
              y={height - 6}
              textAnchor={
                isLine && i === 0 && count > 1
                  ? "start"
                  : isLine && i === count - 1 && count > 1
                    ? "end"
                    : "middle"
              }
              className={cn(
                "text-[0.75rem]/[1rem]",
                active === i ? "fill-(color:--chatcn-fg)" : "fill-(color:--chatcn-fg-subtle)",
              )}
            >
              {l}
            </text>
          ) : null,
        )}
      </g>

      {crosshair !== null ? (
        <line
          x1={Math.round(crosshair) + 0.5}
          x2={Math.round(crosshair) + 0.5}
          y1={PAD_TOP}
          y2={PAD_TOP + plotH}
          stroke="var(--chatcn-border-strong)"
          strokeWidth="1"
        />
      ) : null}

      {type === "bar"
        ? data.map((d, i) => {
            const cx = xOf(i)
            const dim = highlight !== undefined && highlight !== labels[i]
            const isActive = active === i
            let accPos = zeroY
            let accNeg = zeroY
            return (
              <g
                key={labels[i] || i}
                opacity={active !== null && !isActive ? 0.55 : dim ? 0.4 : 1}
                className="transition-opacity duration-150"
              >
                {series.map((s, si) => {
                  const v = toNumber(d[s.key])
                  if (v === null) return null
                  if (stacked) {
                    const h = Math.abs(yOf(v + lo) - yOf(lo))
                    const above = series.slice(si + 1).some((n) => (toNumber(d[n.key]) ?? 0) > 0)
                    if (v >= 0) {
                      accPos -= h
                      return (
                        <path
                          key={s.key}
                          data-slot="chart-mark"
                          data-enter="rise"
                          d={barPath(
                            cx - barW / 2,
                            accPos + (above ? 2 : 0),
                            barW,
                            h - (above ? 2 : 0),
                            "top",
                            !above,
                          )}
                          fill={fillFor(id, si)}
                        />
                      )
                    }
                    const y = accNeg
                    accNeg += h
                    return (
                      <path
                        key={s.key}
                        data-slot="chart-mark"
                        d={barPath(cx - barW / 2, y, barW, h, "bottom")}
                        fill={fillFor(id, si)}
                      />
                    )
                  }
                  const x = multi ? cx - (barW * series.length) / 2 + si * barW : cx - barW / 2
                  const y = Math.min(yOf(v), zeroY)
                  const h = Math.abs(yOf(v) - zeroY)
                  return (
                    <path
                      key={s.key}
                      data-slot="chart-mark"
                      data-enter="rise"
                      // 2 px surface gap between touching bars in a group.
                      d={barPath(
                        x + (multi ? 1 : 0),
                        y,
                        barW - (multi ? 2 : 0),
                        h,
                        v < 0 ? "bottom" : "top",
                      )}
                      // The highlighted bar keeps the series color at full strength; the rest dim.
                      fill={fillFor(id, si)}
                    />
                  )
                })}
                {colLabelFor(labels[i] ?? "") ? (
                  <text
                    x={cx}
                    y={Math.min(yOf(toNumber(d[series[0]?.key ?? ""]) ?? 0), zeroY) - 6}
                    textAnchor="middle"
                    className="fill-(color:--chatcn-fg) text-[0.75rem]/[1rem] tabular-nums"
                  >
                    {valueText(d[series[0]?.key ?? ""], fmt.full)}
                  </text>
                ) : null}
              </g>
            )
          })
        : series.map((s, si) => {
            const stroke = STROKES[si % STROKES.length] as (typeof STROKES)[number]
            const pts = data
              .map((d, i) => ({ i, v: toNumber(d[s.key]) }))
              .filter((p): p is { i: number; v: number } => p.v !== null)
            if (pts.length === 0) return null
            const line = pts.map((p, k) => `${k === 0 ? "M" : "L"}${xOf(p.i)},${yOf(p.v)}`).join("")
            const first = pts[0] as { i: number; v: number }
            const last = pts[pts.length - 1] as { i: number; v: number }
            const area = `${line}L${xOf(last.i)},${zeroY}L${xOf(first.i)},${zeroY}Z`
            return (
              <g key={s.key}>
                <g data-slot="chart-mark" data-enter="draw">
                  {type === "area" ? (
                    <path d={area} fill={stroke.color} opacity={multi ? 0.06 : 0.1} />
                  ) : null}
                  <path
                    d={line}
                    fill="none"
                    stroke={stroke.color}
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeDasharray={stroke.dash}
                  />
                </g>
                {/* The newest point streams in with a fade; the end marker rides it. */}
                <g key={last.i} data-slot="chart-mark" data-enter="fade">
                  <MarkerShape
                    marker={stroke.marker}
                    x={xOf(last.i)}
                    y={yOf(last.v)}
                    color={stroke.color}
                  />
                </g>
                {active !== null &&
                data[active] &&
                toNumber(data[active]?.[s.key]) !== null &&
                active !== last.i ? (
                  <MarkerShape
                    marker={stroke.marker}
                    x={xOf(active)}
                    y={yOf(toNumber(data[active]?.[s.key]) as number)}
                    color={stroke.color}
                  />
                ) : null}
              </g>
            )
          })}

      {showEnds
        ? ends.map((e) => (
            <text
              key={e.s.key}
              x={gutter + plotW + 10}
              y={e.y}
              dy="0.35em"
              className="fill-(color:--chatcn-fg-muted) text-[0.75rem]/[1rem]"
            >
              {truncate(e.text, endW - 12)}
            </text>
          ))
        : null}
    </PlotFrame>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Table view (the text alternative, visible on demand)
 * -----------------------------------------------------------------------------------------------*/

function ChartTable({
  data,
  xKey,
  series,
  format,
  caption,
  hidden,
  id,
}: {
  data: ChartDatum[]
  xKey: string
  series: Required<ChartSeries>[]
  format: (v: number) => string
  caption: string
  hidden: boolean
  id?: string
}) {
  return (
    <div
      data-slot="chart-table"
      className={cn(hidden ? "sr-only" : "chatcn-scroll max-h-80 overflow-auto")}
      tabIndex={hidden ? undefined : 0}
    >
      <table id={id} className="text-[0.8125rem]/[1.25rem] w-full border-collapse">
        <caption className="sr-only">{caption}</caption>
        <thead>
          <tr className="border-(color:--chatcn-border) border-b">
            <th
              scope="col"
              className="text-(color:--chatcn-fg-subtle) text-[0.75rem]/[1rem] py-1.5 pe-3 text-start font-medium"
            >
              {humanize(xKey)}
            </th>
            {series.map((s) => (
              <th
                key={s.key}
                scope="col"
                className="text-(color:--chatcn-fg-subtle) text-[0.75rem]/[1rem] py-1.5 ps-3 text-end font-medium"
              >
                {s.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((d, i) => (
            <tr key={i} className="border-(color:--chatcn-border)/60 border-b last:border-b-0">
              <th scope="row" className="text-(color:--chatcn-fg) py-1.5 pe-3 text-start font-normal">
                {String(d[xKey] ?? "")}
              </th>
              {series.map((s) => {
                const v = toNumber(d[s.key])
                return (
                  <td key={s.key} className="text-(color:--chatcn-fg) py-1.5 ps-3 text-end tabular-nums">
                    {v === null ? <span className="text-(color:--chatcn-fg-subtle)">-</span> : format(v)}
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

export function Chart({
  type = "bar",
  data: dataProp,
  xKey = "label",
  series: seriesProp,
  title,
  description,
  layout = "vertical",
  stacked = false,
  height = 200,
  valueFormat,
  unit,
  currency,
  format,
  locale,
  domain,
  expectedCount,
  valueLabels = "auto",
  highlight,
  summary,
  loading = false,
  streaming = false,
  error,
  empty,
  footer,
  variant = "card",
  view: viewProp,
  defaultView = "chart",
  onViewChange,
  className,
  ...props
}: ChartProps) {
  const data = React.useMemo(
    () => (dataProp ?? []).filter((d): d is ChartDatum => typeof d === "object" && d !== null),
    [dataProp],
  )
  const series = React.useMemo(() => normalizeSeries(seriesProp), [seriesProp])
  const fmt = React.useMemo(
    () => makeFormatter({ format, valueFormat, unit, currency, locale }),
    [format, valueFormat, unit, currency, locale],
  )
  const [measure, width] = useWidth<HTMLDivElement>()
  const [viewState, setViewState] = React.useState(defaultView)
  const view = viewProp ?? viewState
  const setView = (next: "chart" | "table") => {
    if (viewProp === undefined) setViewState(next)
    onViewChange?.(next)
  }
  const tableId = React.useId()
  // While a spec streams, rows can arrive before their values: wait for one real number, so the
  // skeleton holds instead of an empty plot on a made-up 0 to 1 axis.
  const hasData = data.some((d) =>
    series.some((s) => {
      const v = d[s.key]
      return typeof v === "number" && Number.isFinite(v)
    }),
  )
  const skeleton = loading || (!hasData && streaming)
  const label = summary ?? describe(type, data, xKey, series, fmt.full)
  const caption = typeof title === "string" ? title : "Chart data"
  const isLine = type === "line" || type === "area"
  const [endsFit, setEndsFit] = React.useState(false)
  // Lines label their ends directly; the legend only appears when those labels would collide.
  const legend = series.length > 1 && type !== "proportion" && !(isLine && endsFit)
  const isCard = variant === "card"

  return (
    <figure
      data-slot="chart"
      data-chart-type={type}
      data-streaming={streaming ? "" : undefined}
      aria-busy={skeleton || streaming || undefined}
      className={cn(
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) m-0 flex min-w-0 flex-col gap-3",
        isCard && "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) p-4",
        className,
      )}
      {...props}
    >
      <style href="chatcn-chart" precedence="default">
        {chartCss}
      </style>
      {title || description || hasData || skeleton ? (
        <figcaption className="flex min-w-0 items-start gap-3">
          <div className="flex min-w-0 flex-1 flex-col gap-0.5">
            {title ? (
              <span className="text-(color:--chatcn-fg) font-medium text-balance">{title}</span>
            ) : skeleton ? (
              <span aria-hidden="true" className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) my-1 h-3 w-40" />
            ) : null}
            {description ? (
              <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) text-pretty">
                {description}
              </span>
            ) : null}
          </div>
          {hasData && (!error || view === "table") ? (
            <Tooltip content={view === "chart" ? "Show as table" : "Show as chart"}>
              <Button
                size="icon-sm"
                aria-label={view === "chart" ? "Show as table" : "Show as chart"}
                aria-pressed={view === "table"}
                onClick={() => setView(view === "chart" ? "table" : "chart")}
                className="-me-1.5 -mt-1 pointer-coarse:size-11"
              >
                <span
                  key={view}
                  className="grid place-items-center motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]"
                >
                  {view === "chart" ? <TableIcon /> : TYPE_ICON[type]}
                </span>
              </Button>
            </Tooltip>
          ) : null}
        </figcaption>
      ) : null}

      {legend && view === "chart" && hasData && !error ? (
        <ul data-slot="chart-legend" className="flex flex-wrap gap-x-4 gap-y-1" aria-hidden="true">
          {series.map((s, i) => (
            <li
              key={s.key}
              className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) flex items-center gap-1.5"
            >
              <SeriesKey index={i} kind={isLine ? "line" : "fill"} />
              {s.label}
            </li>
          ))}
        </ul>
      ) : null}

      <div ref={measure} className="min-w-0">
        {error && view !== "table" ? (
          <div
            role="alert"
            className="bg-(color:--chatcn-inset) rounded-(--chatcn-radius-md) flex flex-col items-center justify-center gap-1 px-4 text-center"
            style={{ minHeight: type === "proportion" ? 72 : height }}
          >
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) font-medium">Could not draw this chart</p>
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) max-w-sm text-pretty">{error}</p>
            {hasData ? (
              <Button size="sm" variant="outline" className="mt-2" onClick={() => setView("table")}>
                <TableIcon />
                Show the data as a table
              </Button>
            ) : null}
          </div>
        ) : skeleton ? (
          <ChartSkeleton type={type} height={height} layout={layout} />
        ) : !hasData ? (
          <div
            className="bg-(color:--chatcn-inset) rounded-(--chatcn-radius-md) text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) grid place-items-center px-4 text-center"
            style={{ minHeight: type === "proportion" ? 72 : height }}
          >
            {empty ?? "No data to chart."}
          </div>
        ) : view === "table" ? null : type === "proportion" ? (
          <ProportionBar
            role="img"
            aria-label={label}
            items={data.map((d) => ({
              label: String(d[xKey] ?? ""),
              value: toNumber(d[series[0]?.key ?? "value"]) ?? 0,
            }))}
            format={fmt.full}
            streaming={streaming}
            highlight={highlight}
          />
        ) : (
          <Plot
            type={type}
            data={data}
            xKey={xKey}
            series={series}
            layout={layout}
            stacked={stacked}
            height={height}
            width={width}
            fmt={fmt}
            domain={domain}
            expectedCount={streaming ? expectedCount : undefined}
            valueLabels={valueLabels}
            highlight={highlight}
            streaming={streaming}
            summary={label}
            tableId={tableId}
            onEndLabels={setEndsFit}
          />
        )}
        {hasData ? (
          <ChartTable
            id={tableId}
            data={data}
            xKey={xKey}
            series={series}
            format={fmt.full}
            caption={caption}
            hidden={view !== "table"}
          />
        ) : null}
      </div>

      {footer ? <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle)">{footer}</p> : null}
    </figure>
  )
}

export default Chart

