"use client"

import * as React from "react"
import { Chart, ChartProps } from "@/components/ui/chart"

const reducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches

/** Three charts an assistant might answer with, each streamed in point by point. */
const CHARTS: (ChartProps & { data: NonNullable<ChartProps["data"]> })[] = [
  {
    type: "line",
    title: "Failing tests per fix attempt",
    description: "The agent reruns the suite of 443 tests after each change",
    xKey: "run",
    data: [
      { run: "1", passed: 412, failed: 31 },
      { run: "2", passed: 418, failed: 25 },
      { run: "3", passed: 426, failed: 17 },
      { run: "4", passed: 431, failed: 12 },
      { run: "5", passed: 437, failed: 6 },
      { run: "6", passed: 440, failed: 3 },
      { run: "7", passed: 443, failed: 0 },
    ],
    series: [{ key: "failed", label: "Failing" }],
